(function(){
  'use strict';
  const YEARS=[2026,2025,2024,2023,2022,2021];
  const SOURCE_BASE='https://www.upsc.gov.in/sites/default/files/';
  const ARCHIVE='https://www.upsc.gov.in/examinations/previous-question-papers';
  const PAPER_PAGE_2026='https://www.upsc.gov.in/examinations/Civil%20Services%20%28Preliminary%29%20Examination%2C%202026';
  const SOURCES={
    2026:{url:SOURCE_BASE+'QP_CSP_2026_GENERAL_STUDIES_PAPER-II_25052026.pdf',page:PAPER_PAGE_2026,upload:'25 May 2026'},
    2025:{url:SOURCE_BASE+'QP-CSP-25-GENERAL-STUDIES-PAPER-II-26052025.pdf',page:ARCHIVE,upload:'Listed on UPSC previous question papers'},
    2024:{url:SOURCE_BASE+'QP-CSP-24-GENERAL-STUDIES-PAPER-II-180624.pdf',page:ARCHIVE,upload:'Listed on UPSC previous question papers'},
    2023:{url:SOURCE_BASE+'QP_CS_Pre_Exam_2023_GENERAL_STUDIES_PAPER_II_280523.pdf',page:ARCHIVE,upload:'Listed in UPSC archives'},
    2022:{url:SOURCE_BASE+'GENERAL%20STUDIES%20PAPER%20II.pdf',page:ARCHIVE,upload:'Listed in UPSC archives'},
    2021:{url:SOURCE_BASE+'QP-CSP-21-GeneralStudiesPaper-II-121021.pdf',page:ARCHIVE,upload:'Listed in UPSC archives'}
  };
  const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>Array.from(root.querySelectorAll(s));
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const val=(x)=>esc(x??'');
  let page='dashboard', currentResultId=null, reviewFilter='all', importMode='bank', searchTerm='', paletteFilter='all';
  const main=$('#main-content');

  function getQuestions(){return CSATStorage.allQuestions();}
  function qMap(){return new Map(getQuestions().map(q=>[String(q.id),q]));}
  function questionById(id){return qMap().get(String(id));}
  function userAttempts(){return CSATStorage.list(CSATStorage.KEYS.attempts);}
  function savedBookmarks(){return CSATStorage.list(CSATStorage.KEYS.bookmarks);}
  function savedNotes(){return CSATStorage.object(CSATStorage.KEYS.notes);}
  function savedMistakes(){return CSATStorage.object(CSATStorage.KEYS.mistakes);}
  function settings(){return CSATStorage.getSettings();}
  function meta(year){return {year,questions:CSATStorage.getQuestions(year),source:SOURCES[year]};}
  function sourceLink(year){return SOURCES[year]?.url||ARCHIVE;}
  function completeness(qs){
    const text=qs.filter(q=>typeof q.question_text==='string'&&q.question_text.trim()).length;
    const options=qs.filter(q=>Array.isArray(q.options)&&q.options.length===4&&new Set(q.options.map((o,i)=>String(o?.id||o?.option||['A','B','C','D'][i]).toUpperCase())).size===4&&q.options.every(o=>o&&String(o.text??o.value??o).trim())).length;
    const keys=qs.filter(q=>{const k=q.correct_option||q.correctOption;return k&&Array.isArray(q.options)&&q.options.some((o,i)=>String(o?.id||o?.option||['A','B','C','D'][i]).toUpperCase()===String(k).toUpperCase());}).length;
    const solutions=qs.filter(q=>String(q.explanation||q.solution||'').trim()).length;
    const ids=qs.map(q=>String(q?.id??'').trim());
    const idsComplete=ids.length===qs.length&&ids.every(Boolean)&&new Set(ids).size===qs.length;
    const numbers=qs.map(q=>Number(q?.question_number));
    const sortedNumbers=[...numbers].sort((a,b)=>a-b);
    const numbersComplete=qs.length===80&&numbers.every(Number.isInteger)&&new Set(numbers).size===80&&sortedNumbers.every((n,i)=>n===i+1);
    const expectedComplete=qs.length===80&&text===80&&options===80&&keys===80&&solutions===80&&idsComplete&&numbersComplete;
    return {count:qs.length,text,options,keys,solutions,idsComplete,numbersComplete,complete:expectedComplete,baseComplete:qs.length>0&&text===qs.length&&options===qs.length,fullyKeyed:qs.length>0&&keys===qs.length,fullyExplained:qs.length>0&&solutions===qs.length};
  }
  function fmtNum(n,dp=1){return Number(n||0).toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:dp});}
  function fmtPercent(n){return `${fmtNum(n,1)}%`;}
  function dateShort(v){return v?CSATScoring.fmtDate(v):'Never';}
  function notify(message,type='info'){
    const box=document.createElement('div');box.className='toast '+(type==='error'?'error':type==='success'?'success':'');box.textContent=message;$('#toast-region').appendChild(box);
    setTimeout(()=>box.remove(),3800);
  }
  function applySettings(){
    const s=settings();const prefersDark=window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches;
    const theme=s.theme==='system'?(prefersDark?'dark':'light'):s.theme;
    document.documentElement.dataset.theme=theme;
    const sizes={small:.9,medium:1,large:1.1,xlarge:1.2};document.documentElement.style.setProperty('--font-scale',sizes[s.fontSize]||1);
    document.documentElement.dataset.spacing=s.spacing||'comfortable';document.documentElement.dataset.contrast=s.highContrast?'high':'normal';
    document.documentElement.dataset.reducedMotion=s.reducedMotion?'true':'false';
    $('#storage-status').textContent='Progress saved on this device';
    const mark=savedBookmarks().length,mist=Object.keys(savedMistakes()).length;
    $('#bookmark-count').textContent=mark;$('#mistake-count').textContent=mist;
  }
  function setPage(next){
    if(page==='exam' && next!=='exam' && CSATExamEngine.active()?.status==='active'){
      // The active test remains saved for explicit resume; navigation never silently submits it.
    }
    page=next;
    $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
    const names={dashboard:'Dashboard',library:'PYQ Library',practice:'Section Practice',custom:'Create My Mock',analysis:'PYQ Analysis',analytics:'Performance',bookmarks:'My Bookmarks',mistakes:'Mistake Book',notes:'Personal Notes',settings:'Settings',exam:'Active Mock',results:'Test Results',search:'Search Results',review:'Question Review'};
    $('#breadcrumb-current').textContent=names[page]||'Workspace';
    $('#sidebar').classList.remove('open');
    render();
    window.scrollTo({top:0,behavior:settings().reducedMotion?'auto':'smooth'});
  }
  function pageHead(kicker,title,subtitle,actions=''){
    return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;
  }
  function btn(label,action,kind='secondary',extra=''){return `<button class="button button-${kind}" data-action="${action}" ${extra}>${label}</button>`;}
  function missingDataBanner(){
    return `<div class="status-banner"><span aria-hidden="true">⚠</span><div><strong>Official sources located; structured PYQ bank not yet imported</strong><p>This build deliberately contains no invented questions or unverified answer keys. Import your validated question-bank JSON in Settings to enable exam runs, scoring and question-level analytics. Official PDFs remain available from the library.</p><div style="margin-top:10px">${btn('Import question bank','go-import','primary')} <a class="small" href="${ARCHIVE}" target="_blank" rel="noopener">UPSC question-paper archive ↗</a></div></div></div>`;
  }
  function render(){
    applySettings();
    if(page==='dashboard')main.innerHTML=renderDashboard();
    else if(page==='library')main.innerHTML=renderLibrary();
    else if(page==='practice')main.innerHTML=renderPractice();
    else if(page==='custom')main.innerHTML=renderCustom();
    else if(page==='analysis')main.innerHTML=renderAnalysis();
    else if(page==='analytics')main.innerHTML=renderAnalytics();
    else if(page==='bookmarks')main.innerHTML=renderBookmarks();
    else if(page==='mistakes')main.innerHTML=renderMistakes();
    else if(page==='notes')main.innerHTML=renderNotes();
    else if(page==='settings')main.innerHTML=renderSettings();
    else if(page==='exam')main.innerHTML=renderExam();
    else if(page==='results')main.innerHTML=renderResults();
    else if(page==='review')main.innerHTML=renderReviewPage();
    else if(page==='search')main.innerHTML=renderSearchPage();
    else main.innerHTML=renderDashboard();
    bindDynamic();
  }
  function renderDashboard(){
    const attempts=userAttempts().filter(a=>a.status==='completed'),questions=getQuestions(),bookmarks=savedBookmarks(),mistakes=savedMistakes();
    const analytics=CSATAnalytics.calcAnalytics(attempts);
    const active=CSATExamEngine.active();
    const latest=attempts[0];
    const yearCards=YEARS.slice(0,3).map(y=>{
      const qs=CSATStorage.getQuestions(y),c=completeness(qs),best=attempts.filter(a=>String(a.year)===String(y)).reduce((m,a)=>Math.max(m,Number(a.result?.score||0)),0);
      return `<article class="year-card"><div class="year-top"><div><div class="year-number">${y}</div><div class="small muted">General Studies Paper II</div></div><span class="year-tag ${c.complete?'tag-green':'tag-amber'}">${c.complete?'Ready':'Source linked'}</span></div><div class="year-meta"><div><span>Questions</span><strong>${qs.length||'—'} / 80</strong></div><div><span>Duration</span><strong>120 min</strong></div><div><span>Best score</span><strong>${qs.length?fmtNum(best,2):'—'}</strong></div></div><button class="button button-secondary" data-action="${c.complete?'start-year':'go-library'}" data-year="${y}" ${c.complete?'':'title="Open the PYQ Library for official paper links"'}>${c.complete?'Start full mock':'Open paper / details'}</button></article>`;
    }).join('');
    const resume=active&&active.status==='active'?`<div class="card" style="margin-bottom:16px"><div class="row between"><div><div class="eyebrow">Unfinished test</div><h2 style="margin-bottom:3px">${val(active.title)}</h2><p class="small" style="margin:0">${active.questionIds.length} questions · ${CSATScoring.fmtTime(active.remainingSeconds)} remaining</p></div><div class="row">${btn('Resume','resume-test','primary')}${btn('Discard','discard-test','danger')}</div></div></div>`:'';
    return `${pageHead('PERSONAL PREPARATION SYSTEM','UPSC CSAT Command Centre','A structured workspace for previous-year papers, timed mocks and evidence-based performance review.',btn('Create custom mock','go-custom','primary'))}
      ${resume}
      <section class="hero-card card" style="margin-bottom:18px"><div style="z-index:1"><div class="hero-kicker">CIVIL SERVICES PRELIMS · PAPER II</div><div class="hero-title">Prepare for CSAT with a repeatable, measurable process.</div><p style="max-width:520px;margin:14px 0 18px;font-size:13px">Attempt official past papers, review solutions and identify weak topics. All personal progress stays in this browser.</p><div class="row" style="flex-wrap:wrap">${btn('Browse PYQ library','go-library','primary')}${btn('Practice by section','go-practice','secondary')}</div></div><div class="hero-stats"><div class="hero-stat"><strong>${analytics.tests}</strong><span>Completed tests</span></div><div class="hero-stat"><strong>${analytics.questionsAttempted}</strong><span>Questions attempted</span></div><div class="hero-stat"><strong>${analytics.tests?fmtPercent(analytics.accuracy):'—'}</strong><span>Average accuracy</span></div><div class="hero-stat"><strong>${Object.keys(mistakes).length}</strong><span>Questions in mistake book</span></div></div></section>
      ${questions.length?`<div class="grid grid-4" style="margin-bottom:24px"><div class="card metric-card"><span class="metric-symbol">✓</span><div class="metric-label">Tests attempted</div><div class="metric-value">${analytics.tests}</div><div class="metric-foot">Completed test records</div></div><div class="card metric-card"><span class="metric-symbol">◎</span><div class="metric-label">Average score</div><div class="metric-value">${analytics.tests?fmtNum(analytics.averageScore,2):'—'}</div><div class="metric-foot">Out of 200 for full-paper tests</div></div><div class="card metric-card"><span class="metric-symbol">↗</span><div class="metric-label">Best score</div><div class="metric-value">${analytics.tests?fmtNum(analytics.bestScore,2):'—'}</div><div class="metric-foot">Across completed attempts</div></div><div class="card metric-card"><span class="metric-symbol">☆</span><div class="metric-label">Bookmarked questions</div><div class="metric-value">${bookmarks.length}</div><div class="metric-foot">Saved for targeted revision</div></div></div>`:''}
      <div class="row between" style="margin-bottom:12px"><div><h2 class="section-title">Quick start</h2><p class="section-description" style="margin:4px 0 0">Most recent papers, with source links and dataset readiness shown separately.</p></div><button class="text-link" data-action="go-library">View all years →</button></div>
      <div class="year-grid" style="margin-bottom:24px">${yearCards}</div>
      ${!questions.length?missingDataBanner():''}
      <div class="row between" style="margin:26px 0 12px"><div><h2 class="section-title">Practice tools</h2><p class="section-description" style="margin:4px 0 0">Choose a focused workflow for your next session.</p></div></div>
      <div class="feature-grid" style="margin-bottom:24px"><button class="feature-card" data-action="go-practice"><span class="feature-icon">◎</span><div><strong>Section Practice</strong><span>Filter questions by comprehension, quantitative aptitude, reasoning or mental ability.</span></div></button><button class="feature-card" data-action="go-custom"><span class="feature-icon">＋</span><div><strong>Create My Mock</strong><span>Combine years, topic tags, difficulty and timer settings.</span></div></button><button class="feature-card" data-action="go-analysis"><span class="feature-icon">▥</span><div><strong>PYQ Analysis</strong><span>Inspect year-wise question counts and topic mix from imported records.</span></div></button><button class="feature-card" data-action="go-bookmarks"><span class="feature-icon">☆</span><div><strong>Bookmarks</strong><span>Keep important, difficult or revision-worthy questions together.</span></div></button><button class="feature-card" data-action="go-mistakes"><span class="feature-icon">⚑</span><div><strong>Mistake Book</strong><span>Review the questions answered incorrectly in past attempts.</span></div></button><button class="feature-card" data-action="go-settings"><span class="feature-icon">⇧</span><div><strong>Backup and restore</strong><span>Export your history, settings, notes and bookmarks to JSON.</span></div></button></div>
      <div class="grid grid-2"><section class="card"><div class="card-head"><h2>Recent attempts</h2><button class="text-link" data-action="go-analytics">All analytics →</button></div>${attempts.length?attempts.slice(0,4).map(a=>`<div class="list-row"><div class="feature-icon">◷</div><div class="list-row-main"><div class="list-row-title">${val(a.title||`CSAT ${a.year}`)}</div><div class="list-row-sub">${dateShort(a.finishedAt)} · ${fmtPercent(a.result?.accuracy||0)} accuracy</div></div><strong>${fmtNum(a.result?.score,2)}</strong><button class="icon-button" data-action="open-result" data-id="${val(a.id)}" aria-label="Open result">↗</button></div>`).join(''):`<div class="empty-state"><div class="empty-icon">◷</div><strong>No test history yet</strong><p>After importing a complete question bank, your completed tests will appear here.</p></div>`}</section><section class="card"><div class="card-head"><h2>Data readiness</h2><span class="tag ${questions.length?'tag-amber':'tag-red'}">${questions.length?'Partial dataset':'Awaiting import'}</span></div><div class="row between small"><span class="muted">Structured questions loaded</span><strong>${questions.length}</strong></div><div class="progress-bar" style="margin:8px 0 13px"><span style="width:${Math.min(100,questions.length/480*100)}%"></span></div><div class="row between small"><span class="muted">Years with official paper links</span><strong>6 / 6</strong></div><div class="progress-bar" style="margin:8px 0 13px"><span style="width:100%"></span></div><p class="page-note">The official PDFs are source links, not a substitute for verified structured data. This installation has no transcribed questions, answer keys or generated solutions until a dataset is imported.</p>${btn('Open data import','go-import','secondary')}</section></div>`;
  }
  function renderLibrary(){
    return `${pageHead('OFFICIAL PAST PAPERS','PYQ Library','Choose a year, open the original UPSC paper, or launch a structured mock once verified question data is available.',btn('Import dataset','go-import','primary'))}
      ${!getQuestions().length?missingDataBanner():''}
      <div class="year-grid">${YEARS.map(y=>{
        const c=completeness(CSATStorage.getQuestions(y));const best=userAttempts().filter(a=>String(a.year)===String(y)&&a.status==='completed').reduce((m,a)=>Math.max(m,Number(a.result?.score||0)),0);
        return `<article class="year-card"><div class="year-top"><div><div class="year-number">${y}</div><div class="small muted">CS Civil Services Prelims</div></div><span class="year-tag ${c.complete?'tag-green':'tag-amber'}">${c.complete?'Ready':'Not imported'}</span></div><p class="small muted" style="margin-bottom:14px">General Studies Paper II · CSAT</p><div class="year-meta"><div><span>Loaded</span><strong>${c.count} / 80</strong></div><div><span>Answer keys</span><strong>${c.count?`${c.keys}/${c.count}`:'—'}</strong></div><div><span>Best score</span><strong>${best?fmtNum(best,2):'—'}</strong></div></div><div class="stack" style="gap:7px"><button class="button button-primary" data-action="start-year" data-year="${y}" ${c.complete?'':'disabled'}>${c.complete?'Start full CSAT mock':'Mock unavailable'}</button><a class="button button-secondary" href="${sourceLink(y)}" target="_blank" rel="noopener" style="text-align:center">Open official PDF ↗</a><a class="small" href="${SOURCES[y].page}" target="_blank" rel="noopener">Official listing / metadata ↗</a></div><div class="page-note" style="margin-top:11px">${c.complete?'Question text, key and solution coverage checked at load.':`${SOURCES[y].upload}. Structured bank and solutions not included in this build.`}</div></article>`;
      }).join('')}</div>
      <div class="card" style="margin-top:22px"><div class="card-head"><h2>Original paper reference</h2><span class="tag">Primary source: UPSC</span></div><p class="page-note">The links below point to the Union Public Service Commission's official PDF files. The app does not alter the source documents. The exact paper wording and page-level layout should be checked against the PDF when preparing the structured question bank.</p><div class="source-list">${YEARS.map(y=>`<div class="source-row"><div><div class="source-year">CSAT ${y}</div><p>General Studies Paper II · Official UPSC source</p></div><div class="source-links"><a href="${sourceLink(y)}" target="_blank" rel="noopener">Open PDF ↗</a><a href="${SOURCES[y].page}" target="_blank" rel="noopener">Source page ↗</a></div></div>`).join('')}</div></div>`;
  }
  function topicOptions(){const ts=[...new Set(getQuestions().flatMap(q=>[q.topic,q.subtopic].filter(Boolean)))].sort();return ts;}
  function sectionOptions(){return ['English / Comprehension','Quantitative Aptitude','Logical Reasoning','Data Interpretation','Other Mental Ability'];}
  function matchesSection(q,section){
    if(!section||section==='Mixed')return true;
    const hay=[q.section,q.topic,q.subtopic,...(q.tags||[])].join(' ').toLowerCase();
    const s=section.toLowerCase();
    if(s==='english / comprehension'||s==='comprehension')return /comprehension|english|passage|inference/.test(hay);
    if(s==='quantitative aptitude')return /quant|math|number system|percentage|ratio|average|profit|interest|algebra|geometry|mensuration|probability|permutation|time & work|time and work|speed|distance/.test(hay);
    if(s==='logical reasoning'||s==='reasoning')return /reason|logic|statement|conclusion|assumption|syllogism|puzzle|arrangement|coding|deduction|decision/.test(hay);
    if(s==='data interpretation')return /data interpretation|di|table|chart|graph/.test(hay);
    if(s==='other mental ability'||s==='mental ability')return /mental|pattern|relationship|analytical/.test(hay)||(!/comprehension|english|quant|math|reason|logic|data interpretation/.test(hay));
    return hay.includes(s);
  }
  function renderPractice(){
    const yrs=YEARS.map(y=>`<option value="${y}">${y}</option>`).join('');
    const topics=topicOptions().map(t=>`<option value="${val(t)}">${val(t)}</option>`).join('');
    return `${pageHead('TARGETED DRILLS','Section Practice','Build a focused practice set from imported PYQs. Choose a section, narrow it to a topic, then practise timed or untimed.',btn('View PYQ library','go-library','secondary'))}
      ${getQuestions().length?`<div class="grid grid-2"><section class="card"><h2>Configure practice</h2><p class="section-description">Questions are sampled only from records present in your local question bank.</p><form id="practice-form" class="stack"><div class="form-grid"><div class="field"><label for="practice-year">Year</label><select id="practice-year"><option value="all">All years (2021–2026)</option>${yrs}</select></div><div class="field"><label for="practice-section">Section</label><select id="practice-section"><option>English / Comprehension</option><option>Quantitative Aptitude</option><option>Logical Reasoning</option><option>Data Interpretation</option><option>Other Mental Ability</option><option>Mixed</option></select></div><div class="field"><label for="practice-topic">Topic</label><select id="practice-topic"><option value="all">All topics</option>${topics}</select></div><div class="field"><label for="practice-count">Number of questions</label><select id="practice-count"><option>10</option><option>20</option><option>30</option><option>50</option><option>80</option><option value="all">All matching questions</option></select></div><div class="field"><label for="practice-mode">Mode</label><select id="practice-mode"><option value="practice">Practice Mode</option><option value="exam">Exam Mode</option></select></div><div class="field"><label for="practice-timing">Timing</label><select id="practice-timing"><option value="untimed">Untimed</option><option value="timed">Timed</option></select></div><div class="field"><label for="practice-minutes">Timer (minutes)</label><input type="number" id="practice-minutes" value="30" min="1" max="240"></div><div class="field"><label for="practice-order">Question order</label><select id="practice-order"><option value="sequential">Sequential</option><option value="random">Random</option></select></div></div><div class="divider"></div><div class="row between"><div><strong class="small">Available questions</strong><div class="field-help" id="practice-available">${getQuestions().length} loaded in total</div></div><button class="button button-primary" type="submit">Start practice →</button></div></form></section><section class="card"><h2>Practice rules</h2><div class="list-row"><div class="feature-icon">01</div><div class="list-row-main"><div class="list-row-title">Practice Mode</div><div class="list-row-sub">After submission, view the answer and explanation for each keyed question.</div></div></div><div class="list-row"><div class="feature-icon">02</div><div class="list-row-main"><div class="list-row-title">Exam Mode</div><div class="list-row-sub">Answers and explanations stay hidden while the test is active.</div></div></div><div class="list-row"><div class="feature-icon">03</div><div class="list-row-main"><div class="list-row-title">Integrity checks</div><div class="list-row-sub">Questions missing options, answer keys or solutions are excluded from scored practice.</div></div></div><div class="status-banner info" style="margin-top:18px"><span>i</span><div><strong>Local data only</strong><p>Your selected answers, timer and question-level time are autosaved in this browser.</p></div></div></section></div>`:`${missingDataBanner()}<div class="card"><div class="empty-state"><div class="empty-icon">◎</div><strong>Section practice is ready for data</strong><p>Import structured questions with verified answer keys and original explanations in Settings. This prevents invented or unscored questions from entering your practice set.</p>${btn('Import question bank','go-import','primary')}</div></div>`}`;
  }
  function renderCustom(){
    const qs=getQuestions(),topics=topicOptions();
    return `${pageHead('PERSONALISED TEST BUILDER','Create My Mock','Compose a custom paper using question-bank records. Use year, section, topic and difficulty filters together.',btn('Open settings / data import','go-import','secondary'))}
      ${!qs.length?missingDataBanner():''}
      <form id="custom-form" class="grid grid-2"><section class="card"><h2>Question selection</h2><p class="section-description">Pick one or more years and the content filters.</p><div class="field"><label>Years</label><div class="check-grid">${YEARS.map(y=>`<label class="check-tile"><input type="checkbox" name="custom-year" value="${y}"> CSAT ${y}</label>`).join('')}<label class="check-tile"><input type="checkbox" id="custom-all-years" checked> All years</label></div></div><div class="divider"></div><div class="field"><label>Sections</label><div class="check-grid">${['English / Comprehension','Quantitative Aptitude','Logical Reasoning','Data Interpretation','Other Mental Ability'].map((s,i)=>`<label class="check-tile"><input type="checkbox" name="custom-section" value="${val(s)}" ${i===0||i===1||i===2||i===3||i===4?'checked':''}> ${val(s)}</label>`).join('')}<label class="check-tile"><input type="checkbox" id="custom-mixed"> Mixed / all sections</label></div></div><div class="divider"></div><div class="form-grid"><div class="field"><label for="custom-topic">Topic contains</label><input id="custom-topic" type="text" placeholder="e.g. Percentage, inference"></div><div class="field"><label for="custom-difficulty">Difficulty</label><select id="custom-difficulty"><option value="all">All difficulty levels</option><option>Easy</option><option>Moderate</option><option>Difficult</option></select></div></div></section><section class="card"><h2>Test configuration</h2><p class="section-description">Timed tests store remaining time and recover after refresh.</p><div class="stack"><div class="field"><label for="custom-count">Number of questions</label><select id="custom-count"><option value="10">10 questions</option><option value="20">20 questions</option><option value="30">30 questions</option><option value="50">50 questions</option><option value="80">80 questions</option><option value="all">All filtered questions</option></select></div><div class="field"><label for="custom-mode">Mode</label><select id="custom-mode"><option value="exam">Exam Mode (answers hidden)</option><option value="practice">Practice Mode (feedback after test)</option></select></div><div class="field"><label for="custom-duration">Duration (minutes)</label><input id="custom-duration" type="number" min="1" max="240" value="120"></div><div class="field"><label for="custom-order">Question order</label><select id="custom-order"><option value="random">Randomise selected questions</option><option value="sequential">Keep year/question order</option></select></div><div class="status-banner info"><span>i</span><div><strong>Official marking defaults</strong><p>+2.5 for a correct answer and −0.8333 for a wrong answer (one-third penalty), out of 200 for a complete 80-question paper. Scores are raw scores, not UPSC cutoff predictions.</p></div></div><button class="button button-primary" type="submit">Build and start mock →</button></div></section></form>`;
  }
  function renderAnalysis(){
    const questions=getQuestions();
    return `${pageHead('QUESTION-PAPER PATTERN','PYQ Analysis','Inspect topic distribution and year-wise patterns from the records loaded into your question bank. Difficulty labels are analytical, not official UPSC classifications.',btn('Import / update data','go-import','primary'))}
      ${!questions.length?missingDataBanner():''}
      <div class="grid grid-3" style="margin-bottom:18px"><div class="card metric-card"><div class="metric-label">Structured questions</div><div class="metric-value">${questions.length}</div><div class="metric-foot">Imported across all years</div></div><div class="card metric-card"><div class="metric-label">Topic labels</div><div class="metric-value">${topicOptions().length}</div><div class="metric-foot">Primary topics identified</div></div><div class="card metric-card"><div class="metric-label">Years represented</div><div class="metric-value">${YEARS.filter(y=>CSATStorage.getQuestions(y).length).length} / 6</div><div class="metric-foot">2021 through 2026</div></div></div>
      <div class="card" style="margin-bottom:18px"><div class="card-head"><h2>Year-wise coverage and validation</h2><span class="tag">Source data audit</span></div><div class="table-wrap"><table><thead><tr><th>Year</th><th>Questions loaded</th><th>Expected</th><th>Answer key</th><th>Solutions</th><th>Bank status</th><th>Official PDF</th></tr></thead><tbody>${YEARS.map(y=>{const q=CSATStorage.getQuestions(y),c=completeness(q);return `<tr><td><strong>${y}</strong></td><td>${c.count}</td><td>80</td><td>${c.count?`${c.keys}/${c.count}`:'0'}</td><td>${c.count?`${c.solutions}/${c.count}`:'0'}</td><td><span class="tag ${c.complete?'tag-green':'tag-amber'}">${c.complete?'Validated':'Incomplete'}</span></td><td><a href="${sourceLink(y)}" target="_blank" rel="noopener">Open ↗</a></td></tr>`}).join('')}</tbody></table></div><p class="page-note" style="margin-top:12px">No trend conclusion is inferred from missing years. A year is counted as ready only when it has 80 questions, text, options, answer keys and explanations.</p></div>
      <div class="grid grid-2"><section class="card"><div class="card-head"><h2>Question count by year</h2></div>${CSATAnalytics.barChart(YEARS.map(y=>({year:String(y),count:CSATStorage.getQuestions(y).length})),'year','count',80)}</section><section class="card"><div class="card-head"><h2>Topic frequency</h2></div>${(()=>{const counts={};questions.forEach(q=>{const t=q.topic||q.subtopic||'Unclassified';counts[t]=(counts[t]||0)+1;});return CSATAnalytics.barChart(Object.entries(counts).map(([topic,count])=>({topic,count})).sort((a,b)=>b.count-a.count).slice(0,10),'topic','count');})()}</section></div>`;
  }
  function renderAnalytics(){
    const a=CSATAnalytics.calcAnalytics(userAttempts());
    return `${pageHead('PERFORMANCE REVIEW','My Performance','Track results from completed attempts. Topic insights are calculated from answer records, not inferred learner traits.',btn('View history','go-results-history','secondary'))}
      <div class="grid grid-4" style="margin-bottom:18px"><div class="card metric-card"><div class="metric-label">Tests completed</div><div class="metric-value">${a.tests}</div><div class="metric-foot">Saved attempts</div></div><div class="card metric-card"><div class="metric-label">Average score</div><div class="metric-value">${a.tests?fmtNum(a.averageScore,2):'—'}</div><div class="metric-foot">Raw score</div></div><div class="card metric-card"><div class="metric-label">Best score</div><div class="metric-value">${a.tests?fmtNum(a.bestScore,2):'—'}</div><div class="metric-foot">Across completed attempts</div></div><div class="card metric-card"><div class="metric-label">Average accuracy</div><div class="metric-value">${a.tests?fmtPercent(a.accuracy):'—'}</div><div class="metric-foot">Correct / questions with known keys</div></div></div>
      <div class="grid grid-2" style="margin-bottom:18px"><section class="card"><div class="card-head"><h2>Average score by year</h2></div>${CSATAnalytics.barChart(a.years,'year','score',200)}</section><section class="card"><div class="card-head"><h2>Accuracy by year</h2></div>${CSATAnalytics.barChart(a.years,'year','accuracy',100)}</section></div>
      <div class="grid grid-2"><section class="card"><div class="card-head"><h2>Topic accuracy</h2></div>${CSATAnalytics.barChart(a.topics.filter(t=>t.attempted).sort((x,y)=>y.accuracy-x.accuracy).slice(0,10),'topic','accuracy',100)}</section><section class="card"><div class="card-head"><h2>Topic-level time</h2></div>${a.topics.some(t=>t.attempted)?`<div class="bar-list">${a.topics.filter(t=>t.attempted).sort((x,y)=>y.avgTime-x.avgTime).slice(0,10).map(t=>`<div class="bar-row"><span>${val(t.topic)}</span><div class="bar-track"><span style="width:${Math.min(100,t.avgTime/180*100)}%"></span></div><strong>${CSATScoring.fmtTime(t.avgTime)}</strong></div>`).join('')}</div>`:`<div class="empty-state"><strong>No timing data yet</strong><p>Complete a timed test to compare average time by topic.</p></div>`}</section></div>
      <section class="card" style="margin-top:18px"><div class="card-head"><h2>Attempt history</h2><span class="tag">${userAttempts().length} records</span></div>${userAttempts().length?`<div class="table-wrap"><table><thead><tr><th>Test</th><th>Date</th><th>Score</th><th>Accuracy</th><th>Time taken</th><th></th></tr></thead><tbody>${userAttempts().filter(x=>x.status==='completed').map(a=>`<tr><td>${val(a.title)}</td><td>${dateShort(a.finishedAt)}</td><td>${fmtNum(a.result?.score,2)}</td><td>${fmtPercent(a.result?.accuracy||0)}</td><td>${CSATScoring.fmtTime(a.result?.totalTime||0)}</td><td><button class="text-link" data-action="open-result" data-id="${val(a.id)}">Review →</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>No completed tests yet</strong><p>Test history appears after a mock is submitted.</p></div>`}</section>`;
  }
  function renderBookmarks(){
    const list=savedBookmarks();
    return `${pageHead('REVISION QUEUE','My Bookmarks','Save questions under categories such as Important, Difficult, Revise, Mistake, Formula or Doubt.',btn('Go to PYQ library','go-library','secondary'))}
      ${list.length?`<div class="row between" style="margin-bottom:14px"><span class="small muted">${list.length} saved questions</span><button class="button button-secondary" data-action="retry-bookmarks">Retry all available</button></div><div class="stack">${list.map(b=>{const q=questionById(b.questionId);return `<article class="card"><div class="row between"><div><span class="tag">${val(b.category||'Important')}</span><span class="small muted" style="margin-left:8px">CSAT ${val(b.year||q?.year||'—')} · Q${val(q?.question_number||b.question_number||'—')}</span></div><button class="icon-button" data-action="remove-bookmark" data-id="${val(b.questionId)}" aria-label="Remove bookmark">×</button></div><h3 style="margin-top:12px">${val(q?.question_text||'Question is not present in the currently imported bank')}</h3><div class="row" style="flex-wrap:wrap">${q?btn('Retry question','retry-question','primary',`data-id="${val(q.id)}"`):''}${q?btn('View explanation','view-question','secondary',`data-id="${val(q.id)}"`):''}<span class="page-note">Saved ${dateShort(b.addedAt)}</span></div></article>`}).join('')}</div>`:`<div class="card"><div class="empty-state"><div class="empty-icon">☆</div><strong>No bookmarked questions</strong><p>Bookmark a question during review, or add one from the question bank.</p>${btn('Browse questions','go-library','primary')}</div></div>`}`;
  }
  function renderMistakes(){
    const mistakes=Object.values(savedMistakes()).sort((a,b)=>new Date(b.lastAttempted||0)-new Date(a.lastAttempted||0));
    return `${pageHead('ERROR CORRECTION','Mistake Book','Questions you answered incorrectly are saved here automatically. Retry attempts are kept separate from original mock history.',btn('Retry all mistakes','retry-mistakes','primary',mistakes.length?'':'disabled'))}
      ${mistakes.length?`<div class="row between" style="margin-bottom:14px"><span class="small muted">${mistakes.length} questions tracked</span>${btn('Clear all mistakes','clear-mistakes','danger')}</div><div class="stack">${mistakes.map(m=>{const q=questionById(m.questionId);return `<article class="card"><div class="row between"><div><span class="tag tag-red">${m.count||1} × incorrect</span><span class="small muted" style="margin-left:8px">CSAT ${val(q?.year||m.year||'—')} · Q${val(q?.question_number||'—')}</span></div><span class="small muted">Last: ${dateShort(m.lastAttempted)}</span></div><h3 style="margin-top:12px">${val(q?.question_text||'Question is not in the currently imported bank')}</h3><div class="list-row"><div class="list-row-main"><div class="list-row-sub">Your last answer: <strong>${val(m.lastAnswer||'—')}</strong> · Correct answer: <strong>${val(q?.correct_option||m.correctOption||'—')}</strong></div><div class="list-row-sub">Topic: ${val(q?.topic||q?.subtopic||'Unclassified')}</div></div></div><div class="row" style="flex-wrap:wrap">${q?btn('Retry','retry-question','primary',`data-id="${val(q.id)}"`):''}${btn('Remove','remove-mistake','quiet',`data-id="${val(m.questionId)}"`)}</div></article>`}).join('')}</div>`:`<div class="card"><div class="empty-state"><div class="empty-icon">⚑</div><strong>Your mistake book is empty</strong><p>Wrong answers in a scored attempt can be recorded here automatically. Complete a test to build a useful revision queue.</p></div></div>`}`;
  }
  function renderNotes(){
    const notes=savedNotes(),list=Object.entries(notes).filter(([id,n])=>n&&String(n.text||'').trim()).sort((a,b)=>new Date(b[1].updatedAt||0)-new Date(a[1].updatedAt||0));
    return `${pageHead('PERSONAL REVISION NOTES','My Notes','Store your own formula reminders, shortcuts, doubts and reasoning notes against question IDs. Notes remain on this device.',btn('Export backup','export-backup','secondary'))}
      <section class="card" style="margin-bottom:18px"><div class="card-head"><h2>Search notes</h2><span class="tag">${list.length} saved</span></div><div class="field"><label for="notes-search">Search note text, question or topic</label><input type="search" id="notes-search" placeholder="e.g. ratio method, inference, 2023-Q12" value="${val(searchTerm)}"></div></section>
      ${list.length?`<div class="stack" id="notes-list">${list.map(([id,n])=>{const q=questionById(id);return `<article class="card note-item" data-search="${val([id,n.text,q?.question_text,q?.topic,q?.year].join(' ').toLowerCase())}"><div class="row between"><div class="small muted">${val(q?`CSAT ${q.year} · Q${q.question_number}`:id)} · Updated ${dateShort(n.updatedAt)}</div><div class="row">${q?btn('Retry','retry-question','secondary',`data-id="${val(id)}"`):''}<button class="icon-button" data-action="edit-note" data-id="${val(id)}" aria-label="Edit note">✎</button><button class="icon-button" data-action="delete-note" data-id="${val(id)}" aria-label="Delete note">×</button></div></div><h3 style="margin-top:10px">${val(q?.topic||'Personal note')}</h3><p style="white-space:pre-wrap;font-size:12px;margin-bottom:0">${val(n.text)}</p></article>`}).join('')}</div>`:`<div class="card"><div class="empty-state"><div class="empty-icon">▧</div><strong>No personal notes yet</strong><p>Open a question in practice mode and use Add Note during review.</p></div></div>`}`;
  }
  function renderSettings(){
    const s=settings(),bank=CSATStorage.getBank(),qs=getQuestions(),att=userAttempts();
    const opts=(values,current)=>values.map(([v,t])=>`<option value="${v}" ${current===v?'selected':''}>${t}</option>`).join('');
    return `${pageHead('PREFERENCES & DATA','Settings','Control presentation, exam behavior, accessibility and local data backups.',btn('Export all data','export-backup','primary'))}
      <div class="grid grid-2"><section class="card"><h2>Appearance</h2><div class="setting-group"><div class="setting-heading"><div><h3>Theme</h3><p>System mode follows your device preference.</p></div><div class="setting-control"><select data-setting="theme">${opts([['system','System default'],['light','Light mode'],['dark','Dark mode']],s.theme)}</select></div></div></div><div class="setting-group"><div class="setting-heading"><div><h3>Font size</h3><p>Scale question text and interface elements.</p></div><div class="setting-control"><select data-setting="fontSize">${opts([['small','Small'],['medium','Medium'],['large','Large'],['xlarge','Extra large']],s.fontSize)}</select></div></div></div><div class="setting-group"><div class="setting-heading"><div><h3>Layout density</h3><p>Choose comfortable spacing or a tighter layout.</p></div><div class="setting-control"><select data-setting="spacing">${opts([['comfortable','Comfortable'],['compact','Compact']],s.spacing)}</select></div></div></div></section>
      <section class="card"><h2>Exam preferences</h2>${settingToggle('timerEnabled','Enable timer','Show a countdown for timed tests.',s.timerEnabled)}${settingToggle('timerWarnings','Timer warnings','Highlight the timer when time is running low.',s.timerWarnings)}${settingToggle('autoSubmit','Auto-submit at zero','Submit the attempt when the timer expires.',s.autoSubmit)}${settingToggle('confirmSubmit','Confirm manual submission','Ask before ending an active test.',s.confirmSubmit)}${settingToggle('showPalette','Show question palette','Display status of all questions while testing.',s.showPalette)}${settingToggle('keyboardShortcuts','Keyboard shortcuts','Enable exam navigation shortcuts.',s.keyboardShortcuts)}</section>
      <section class="card"><h2>Accessibility</h2>${settingToggle('highContrast','High contrast','Use stronger outlines and status cues.',s.highContrast)}${settingToggle('reducedMotion','Reduce animations','Minimise nonessential motion.',s.reducedMotion)}<div class="divider"></div><div class="kbd-help"><span><kbd>1–4</kbd> Select option</span><span><kbd>←</kbd> Previous</span><span><kbd>→</kbd> Next</span><span><kbd>M</kbd> Mark</span><span><kbd>C</kbd> Clear</span><span><kbd>S</kbd> Submit dialog</span></div></section>
      <section class="card" id="data-import"><h2>Question-bank data</h2><p class="section-description">Import a prepared, verified JSON question bank. The app does not invent missing text, keys or explanations.</p><div class="status-banner ${qs.length?'info':''}" style="margin-bottom:14px"><span>▤</span><div><strong>${qs.length} structured questions currently loaded</strong><p>${YEARS.map(y=>`${y}: ${CSATStorage.getQuestions(y).length}`).join(' · ')}</p></div></div><button class="button button-primary" data-action="import-bank">Import question-bank JSON</button><div class="divider"></div><h3>Expected question record</h3><pre class="code-sample">{ "year": 2023, "questions": [
  { "id": "2023-Q1", "question_number": 1,
    "section": "Quantitative Aptitude",
    "topic": "Ratio & Proportion",
    "question_text": "Exact official question wording…",
    "options": [{"id":"A","text":"…"}, {"id":"B","text":"…"}, {"id":"C","text":"…"}, {"id":"D","text":"…"}],
    "correct_option": "B",
    "explanation": "Original, checked solution…",
    "source_url": "Official UPSC PDF URL" }
] }</pre><p class="page-note">Each year must contain all 80 questions for full-paper mode. Each question needs four options, one verified correct_option and an original explanation. Topic, difficulty, tags and passage_text are recommended.</p></section>
      <section class="card"><h2>Backup and restore</h2><p class="section-description">Backups include progress, settings, bookmarks, notes, mistakes and imported question data.</p><div class="row" style="flex-wrap:wrap">${btn('Export backup JSON','export-backup','primary')}${btn('Import backup JSON','import-backup','secondary')}</div><p class="page-note" style="margin-top:10px">Importing a backup restores its stored categories. Store backups somewhere outside this browser profile.</p></section>
      <section class="card"><h2>Reset controls</h2><p class="section-description">Resetting progress does not delete the imported question database.</p><div class="row" style="flex-wrap:wrap">${btn('Reset progress','reset-progress','danger')}${btn('Reset settings','reset-settings','quiet')}</div></section>
      <section class="card"><h2>Storage summary</h2><div class="list-row"><div class="list-row-main"><div class="list-row-title">Completed attempts</div><div class="list-row-sub">Saved result history</div></div><strong>${att.length}</strong></div><div class="list-row"><div class="list-row-main"><div class="list-row-title">Bookmarks</div><div class="list-row-sub">Questions in revision queue</div></div><strong>${savedBookmarks().length}</strong></div><div class="list-row"><div class="list-row-main"><div class="list-row-title">Notes</div><div class="list-row-sub">Non-empty personal notes</div></div><strong>${Object.values(savedNotes()).filter(n=>n&&String(n.text||'').trim()).length}</strong></div><div class="list-row"><div class="list-row-main"><div class="list-row-title">Mistakes</div><div class="list-row-sub">Questions tracked after incorrect answers</div></div><strong>${Object.keys(savedMistakes()).length}</strong></div><p class="page-note">Data stays in LocalStorage on this device. Browser private mode, storage cleanup or browser profile deletion can remove it.</p></section></div>`;
  }
  function settingToggle(name,title,desc,checked){return `<div class="setting-group"><div class="setting-heading"><div><h3>${title}</h3><p>${desc}</p></div><label class="switch"><input type="checkbox" data-setting="${name}" ${checked?'checked':''}><span class="switch-ui" aria-hidden="true"></span><span class="sr-only">${title}</span></label></div></div>`;}
  function renderExam(){
    const test=CSATExamEngine.active();
    if(!test||test.status!=='active')return `<div class="card exam-complete"><h1>No active test</h1><p>Start a verified full paper or practice set from the library or practice page.</p>${btn('Open PYQ Library','go-library','primary')}</div>`;
    const map=qMap(),id=String(test.questionIds[test.currentIndex]),q=map.get(id);
    if(!q)return `<div class="status-banner danger"><strong>Question data unavailable</strong><p>The active test refers to question ${val(id)}, which is not in the current question bank. Import the matching data or discard this test.</p>${btn('Discard test','discard-test','danger')}</div>`;
    const c=CSATExamEngine.counts(test),review=new Set(test.reviewIds||[]),marked=review.has(id),answer=test.answers[id]||'',mode=test.mode||'exam',practice=mode==='practice';
    const timeLeft=Number(test.remainingSeconds||0),timerClass=timeLeft<=300?'danger':timeLeft<=600?'warning':'';
    const questionHead=`<div class="exam-top-card card"><div class="exam-title"><small>${val(test.title)} · ${mode==='practice'?'Practice mode':'Exam mode'}</small><strong>Question ${test.currentIndex+1} <span class="muted">/ ${test.questionIds.length}</span></strong></div><div class="row" style="gap:10px"><button class="button button-secondary mobile-palette-toggle" data-action="toggle-palette">Question palette</button>${test.durationSeconds===0?'<span class="tag">Untimed</span>':settings().timerEnabled?`<div class="timer-box ${settings().timerWarnings?timerClass:''}" id="exam-timer" role="timer" aria-label="Time remaining">${CSATScoring.fmtTime(timeLeft)}</div>`:`<span class="tag">Timer off</span>`}</div></div>`;
    const passage=q.passage_text||q.passage||'';
    const revealed=practice&&(test.revealedIds||[]).includes(id);
    const correctKey=q.correct_option||q.correctOption;
    const isRevealedCorrect=answer&&correctKey&&String(answer).toUpperCase()===String(correctKey).toUpperCase();
    const options=(q.options||[]).map((o,i)=>{const letter=String(o.id||o.option||['A','B','C','D'][i]||i+1);const text=o.text??o.value??o;return `<label class="option ${String(answer).toUpperCase()===letter.toUpperCase()?'selected':''}"><input type="radio" name="exam-answer" value="${val(letter)}" ${String(answer).toUpperCase()===letter.toUpperCase()?'checked':''} aria-label="Option ${val(letter)}"><span class="option-letter">${val(letter)}</span><span class="option-text">${val(text)}</span></label>`}).join('');
    return `<div class="exam-shell">${questionHead}<div class="exam-layout"><section class="exam-main"><div class="card question-card"><div class="question-topline"><span class="question-number">CSAT ${val(q.year)} · Q${val(q.question_number)}</span><div class="row"><span class="tag">${val(q.section||q.topic||'CSAT')}</span><button class="text-link" data-action="toggle-bookmark" data-id="${val(q.id)}">${savedBookmarks().some(b=>String(b.questionId)===String(q.id))?'★ Bookmarked':'☆ Bookmark'}</button></div></div>${passage?`<div class="passage" aria-label="Comprehension passage">${val(passage)}</div>`:''}<div class="question-text">${val(q.question_text)}</div><div class="options-list">${options}</div>${revealed?`<div class="solution-block"><div class="answer-hero ${isRevealedCorrect?'':'wrong'}"><strong>Correct answer:</strong> ${val(correctKey)} ${answer?`· Your answer: ${val(answer)} (${isRevealedCorrect?'correct':'incorrect'})`:''}</div><h3>Explanation / solution</h3><div class="solution-text">${val(q.explanation||q.solution||'No explanation is available for this question.')}</div></div>`:''}<div class="question-footer"><div class="question-actions">${practice?`<button class="button button-secondary" data-action="reveal-answer" ${revealed?'disabled':''}>Check answer</button>`:''}<button class="button button-secondary" data-action="clear-answer">Clear response</button><button class="button ${marked?'button-primary':'button-secondary'}" data-action="mark-review">${marked?'✓ Marked for review':'⚑ Mark for review'}</button></div><div class="question-actions"><button class="button button-secondary" data-action="prev-question" ${test.currentIndex===0?'disabled':''}>← Previous</button><button class="button button-primary" data-action="next-question" ${test.currentIndex===test.questionIds.length-1?'disabled':''}>Next →</button></div></div><div class="row between" style="margin-top:14px;flex-wrap:wrap"><span class="page-note">Question time: ${CSATScoring.fmtTime(test.questionTimes[id]||0)} · Autosaved locally</span><button class="button button-danger" data-action="submit-test">Submit test</button></div></div></section>
      <aside class="question-palette ${settings().showPalette?'':'hide'}" id="question-palette"><div class="card card-flat"><div class="card-head"><h2>Question palette</h2><button class="icon-button mobile-menu" data-action="toggle-palette" aria-label="Close question palette">×</button></div><div class="field" style="margin-bottom:12px"><label for="palette-section-filter">Filter palette by section</label><select id="palette-section-filter"><option value="all">All sections</option>${[...new Set(test.questionIds.map(qid=>map.get(String(qid))?.section||'Unclassified'))].map(s=>`<option value="${val(s)}" ${paletteFilter===s?'selected':''}>${val(s)}</option>`).join('')}</select></div><div class="palette-summary"><div><strong>${c.answered}</strong><span>Answered</span></div><div><strong>${c.remaining}</strong><span>Unanswered</span></div><div><strong>${c.review}</strong><span>Review</span></div></div><div class="palette-grid">${test.questionIds.map((qid,i)=>({qid,i,q:map.get(String(qid))})).filter(item=>paletteFilter==='all'||(item.q?.section||'Unclassified')===paletteFilter).map(({qid,i})=>{const qa=test.answers[String(qid)],r=review.has(String(qid)),isCurrent=i===test.currentIndex;const cls=isCurrent?'current':(qa&&r?'answered-review':qa?'answered':r?'review':(new Set(test.visitedIds||[]).has(String(qid))?'visited':''));return `<button class="palette-btn ${cls}" data-action="jump-question" data-index="${i}" aria-label="Go to question ${i+1}${qa?', answered':''}${r?', marked for review':''}" title="Question ${i+1}">${i+1}</button>`}).join('')}</div><div class="palette-legend"><span><i class="legend-dot"></i>Unvisited</span><span><i class="legend-dot visited"></i>Visited</span><span><i class="legend-dot answered"></i>Answered</span><span><i class="legend-dot review"></i>Review</span><span><i class="legend-dot current"></i>Current</span></div><div class="divider"></div><div class="row between"><span class="small muted">Questions attempted</span><strong class="small">${c.answered} / ${c.total}</strong></div><div class="progress-bar" style="margin:9px 0 14px"><span style="width:${c.total?c.answered/c.total*100:0}%"></span></div><button class="button button-danger" style="width:100%" data-action="submit-test">Submit test</button></div></aside></div></div>`;
  }
  function renderResults(){
    const all=userAttempts();let at=all.find(a=>a.id===currentResultId)||all[0];
    if(!at)return `<div class="card"><div class="empty-state"><strong>No result selected</strong><p>Submit a test or select an attempt from Performance.</p>${btn('Open performance','go-analytics','primary')}</div></div>`;
    currentResultId=at.id;
    const r=at.result||{},details=(r.details||[]),map=qMap();
    const sectionStats={};const topicStats={};
    details.forEach(d=>{const q=map.get(String(d.questionId));const sec=q?.section||'Unclassified';if(!sectionStats[sec])sectionStats[sec]={name:sec,attempted:0,correct:0,wrong:0,score:0};if(d.answer){sectionStats[sec].attempted++;if(d.result==='correct'){sectionStats[sec].correct++;sectionStats[sec].score+=2.5;}else if(d.result==='incorrect'){sectionStats[sec].wrong++;sectionStats[sec].score-=2.5/3;}}
      const topic=q?.topic||q?.subtopic||'Unclassified';if(!topicStats[topic])topicStats[topic]={name:topic,attempted:0,correct:0,wrong:0,score:0};if(d.answer){topicStats[topic].attempted++;if(d.result==='correct'){topicStats[topic].correct++;topicStats[topic].score+=2.5;}else if(d.result==='incorrect'){topicStats[topic].wrong++;topicStats[topic].score-=2.5/3;}}
    });
    const qualification=r.qualificationKnown?`<span class="tag ${r.qualified?'tag-green':'tag-red'}">${r.qualified?'Above qualifying benchmark':'Below qualifying benchmark'}</span>`:`<span class="tag tag-amber">Qualification estimate unavailable</span>`;
    return `${pageHead('ATTEMPT SUMMARY','Test Results',`${val(at.title)} · Completed ${dateShort(at.finishedAt)}`,btn('Back to performance','go-analytics','secondary'))}
      <section class="card" style="margin-bottom:18px"><div class="grid grid-4"><div><div class="metric-label">Raw score</div><div class="metric-value">${fmtNum(r.score,2)}</div><div class="metric-foot">Out of ${fmtNum(r.totalMarks,0)} available in this set</div></div><div><div class="metric-label">Accuracy</div><div class="metric-value">${fmtPercent(r.accuracy)}</div><div class="metric-foot">Correct / keyed attempted</div></div><div><div class="metric-label">Attempt rate</div><div class="metric-value">${fmtPercent(r.attemptRate)}</div><div class="metric-foot">${r.attempted} of ${r.total} questions</div></div><div><div class="metric-label">Time used</div><div class="metric-value">${CSATScoring.fmtTime(r.totalTime)}</div><div class="metric-foot">${CSATScoring.fmtTime(r.averageTime)} average per question</div></div></div></section>
      <div class="grid grid-2" style="margin-bottom:18px"><section class="card"><h2>Answer breakdown</h2><div class="grid grid-2"><div><div class="metric-label">Correct</div><div class="metric-value" style="color:var(--green)">${r.correct||0}</div></div><div><div class="metric-label">Incorrect</div><div class="metric-value" style="color:var(--red)">${r.incorrect||0}</div></div><div><div class="metric-label">Unattempted</div><div class="metric-value">${r.unattempted||0}</div></div><div><div class="metric-label">Attempted without answer key</div><div class="metric-value">${r.unkeyedAttempted||0}</div></div></div><div class="divider"></div><div class="row between small"><span class="muted">Positive marks</span><strong>+${fmtNum(r.positiveMarks,2)}</strong></div><div class="row between small" style="margin-top:8px"><span class="muted">Negative marks</span><strong>−${fmtNum(r.negativeMarks,2)}</strong></div><div class="row between small" style="margin-top:8px"><span class="muted">Score formula</span><strong>Correct marks − penalty</strong></div></section><section class="card"><h2>Qualifying benchmark</h2>${r.fullPaper?`<div class="metric-value">${fmtNum(r.qualifyingScore,2)} / 200</div><p class="small muted">33% of the 200-mark Paper II benchmark. This is CSAT's qualifying threshold, not the overall Prelims cutoff.</p>${qualification}<div class="divider"></div><div class="row between small"><span class="muted">Difference from benchmark</span><strong>${r.qualificationKnown?`${r.score-r.qualifyingScore>=0?'+':''}${fmtNum(r.score-r.qualifyingScore,2)}`:'Not reliable'}</strong></div>`:`<div class="status-banner info"><span>i</span><div><strong>Qualifying status not applicable</strong><p>This is a section/custom practice set, not a complete 80-question CSAT paper.</p></div></div>`}${r.unkeyedAttempted?`<div class="status-banner" style="margin-top:12px"><span>!</span><div><strong>Some answers could not be scored</strong><p>${r.unkeyedAttempted} attempted questions lacked an imported correct answer. This result is incomplete.</p></div></div>`:''}</section></div>
      <section class="card" style="margin-bottom:18px"><div class="card-head"><h2>Section-wise performance</h2><span class="tag">Calculated from question tags</span></div><div class="table-wrap"><table><thead><tr><th>Section</th><th>Attempted</th><th>Correct</th><th>Wrong</th><th>Accuracy</th><th>Score</th></tr></thead><tbody>${Object.values(sectionStats).map(s=>`<tr><td>${val(s.name)}</td><td>${s.attempted}</td><td>${s.correct}</td><td>${s.wrong}</td><td>${fmtPercent(s.attempted?s.correct/s.attempted*100:0)}</td><td>${fmtNum(s.score,2)}</td></tr>`).join('')||'<tr><td colspan="6">No section classification available.</td></tr>'}</tbody></table></div></section>
      <section class="card" style="margin-bottom:18px"><div class="card-head"><h2>Topic-wise performance</h2></div><div class="table-wrap"><table><thead><tr><th>Topic</th><th>Attempted</th><th>Correct</th><th>Wrong</th><th>Accuracy</th><th>Score</th></tr></thead><tbody>${Object.values(topicStats).sort((a,b)=>a.name.localeCompare(b.name)).map(s=>`<tr><td>${val(s.name)}</td><td>${s.attempted}</td><td>${s.correct}</td><td>${s.wrong}</td><td>${fmtPercent(s.attempted?s.correct/s.attempted*100:0)}</td><td>${fmtNum(s.score,2)}</td></tr>`).join('')||'<tr><td colspan="6">No topic data available.</td></tr>'}</tbody></table></div></section>
      <section class="card"><div class="card-head"><h2>Question review</h2><span class="tag">${details.length} questions</span></div><div class="review-filter"><label class="small muted" for="result-filter">Show</label><select id="result-filter" style="width:auto"><option value="all" ${reviewFilter==='all'?'selected':''}>All questions</option><option value="incorrect" ${reviewFilter==='incorrect'?'selected':''}>Incorrect</option><option value="correct" ${reviewFilter==='correct'?'selected':''}>Correct</option><option value="unattempted" ${reviewFilter==='unattempted'?'selected':''}>Unattempted</option><option value="unkeyed" ${reviewFilter==='unkeyed'?'selected':''}>Missing answer key</option></select></div><div class="stack">${details.filter(d=>reviewFilter==='all'||d.result===reviewFilter).map(d=>{const q=map.get(String(d.questionId));return `<article class="search-result"><div style="min-width:0"><strong>Q${val(q?.question_number||d.question_number||'—')} · ${val(q?.topic||q?.section||'CSAT')}</strong><p>${val(q?.question_text||'Question not found in current bank')}</p><div class="list-row-sub">Your answer: <strong>${val(d.answer||'Not attempted')}</strong> · Correct answer: <strong>${val(d.key||q?.correct_option||'Not keyed')}</strong> · Time: ${CSATScoring.fmtTime(d.time||0)}</div></div><div class="stack" style="gap:7px;min-width:105px"><span class="question-flag">${val(d.result)}</span>${q?`<button class="button button-secondary" data-action="review-question" data-id="${val(q.id)}" data-attempt="${val(at.id)}">Details</button>`:''}</div></article>`}).join('')||'<div class="empty-state"><strong>No questions in this filter</strong><p>Change the result filter.</p></div>'}</div></section>`;
  }
  function renderReviewPage(){
    const id=window.reviewQuestionId,q=questionById(id),attempt=userAttempts().find(a=>a.id===window.reviewAttemptId),detail=attempt?.result?.details?.find(d=>String(d.questionId)===String(id));
    if(!q)return `<div class="card"><div class="empty-state"><strong>Question unavailable</strong><p>Import the matching question-bank record first.</p>${btn('Settings','go-settings','primary')}</div></div>`;
    const answer=detail?.answer||'',correct=q.correct_option||q.correctOption;
    return `${pageHead('QUESTION REVIEW',`CSAT ${q.year} · Question ${q.question_number}`,'Review your answer, correct answer, reasoning and personal notes.',btn('Back to results','back-results','secondary'))}<div class="card"><div class="question-topline"><span class="tag">${val(q.section||q.topic||'CSAT')}</span><span class="tag ${detail?.result==='correct'?'tag-green':detail?.result==='incorrect'?'tag-red':'tag-amber'}">${val(detail?.result||'Not attempted')}</span></div>${q.passage_text?`<div class="passage">${val(q.passage_text)}</div>`:''}<div class="question-text">${val(q.question_text)}</div><div class="options-list">${(q.options||[]).map((o,i)=>{const letter=o.id||['A','B','C','D'][i]||i+1;const cls=String(letter).toUpperCase()===String(correct).toUpperCase()?'selected':'';return `<div class="option ${cls}"><span class="option-letter">${val(letter)}</span><span class="option-text">${val(o.text??o)}</span>${String(letter).toUpperCase()===String(answer).toUpperCase()?'<span class="question-flag">Your answer</span>':''}</div>`}).join('')}</div><div class="solution-block"><div class="answer-hero ${detail?.result==='incorrect'?'wrong':''}"><strong>Your answer:</strong> ${val(answer||'Not attempted')} &nbsp; · &nbsp; <strong>Correct answer:</strong> ${val(correct||'Not verified')}</div><h3>Explanation / solution</h3><div class="solution-text">${val(q.explanation||q.solution||'No explanation is available for this question yet. Do not treat an absent explanation as verified.')}</div>${q.concept?`<div class="divider"></div><h3>Concept reminder</h3><div class="solution-text">${val(q.concept)}</div>`:''}<div class="divider"></div><div class="form-grid"><div class="field"><label for="review-note">Personal note</label><textarea id="review-note" placeholder="Add a formula, shortcut or doubt…">${val(savedNotes()[String(q.id)]?.text||'')}</textarea><button class="button button-secondary" data-action="save-note" data-id="${val(q.id)}">Save note</button></div><div class="stack"><div><span class="field-label">Topic</span><p class="small">${val(q.topic||'Unclassified')} ${q.subtopic?`/ ${val(q.subtopic)}`:''}</p></div><div><span class="field-label">Difficulty (analytical)</span><p class="small">${val(q.difficulty||'Not classified')}</p></div><div><span class="field-label">Time on question</span><p class="small">${CSATScoring.fmtTime(detail?.time||0)}</p></div><div class="row" style="flex-wrap:wrap">${btn('Retry question','retry-question','primary',`data-id="${val(q.id)}"`)}${btn(savedBookmarks().some(b=>String(b.questionId)===String(q.id))?'Remove bookmark':'Bookmark question','toggle-bookmark','secondary',`data-id="${val(q.id)}"`)}</div></div></div></div></div>`;
  }
  function renderSearchPage(){
    const term=searchTerm.trim().toLowerCase();const all=getQuestions();const notes=savedNotes();
    const qs=all.filter(q=>[q.question_text,q.topic,q.subtopic,q.year,q.section,(q.tags||[]).join(' '),notes[q.id]?.text].join(' ').toLowerCase().includes(term));
    return `${pageHead('QUESTION FINDER','Search Results',`Search questions, topics, years, tags and personal notes for “${val(searchTerm)}”.`,btn('Clear search','clear-search','secondary'))}<div class="field" style="margin-bottom:18px"><label for="search-page-input">Search query</label><input id="search-page-input" type="search" value="${val(searchTerm)}" placeholder="Enter a topic or phrase"></div><p class="small muted">${qs.length} matching question(s)</p><div class="stack">${qs.map(q=>`<article class="search-result"><div><strong>CSAT ${q.year} · Q${q.question_number} — ${val(q.topic||q.section||'CSAT')}</strong><p>${val(q.question_text)}</p><div class="list-row-sub">${val(q.section||'Unclassified')} · ${val(q.difficulty||'Difficulty unclassified')}</div></div><div class="stack" style="gap:7px">${btn('Review','view-question','primary',`data-id="${val(q.id)}"`)}${btn('Bookmark','toggle-bookmark','secondary',`data-id="${val(q.id)}"`)}</div></article>`).join('')||`<div class="empty-state"><strong>No matching questions</strong><p>Try a broader term or import more structured questions.</p></div>`}</div>`;
  }

  function canStartQuestions(qs,full=false){
    if(!qs.length)return {ok:false,reason:'No question records match this selection.'};
    const base=completeness(qs);const broken=qs.filter(q=>!q.question_text||!Array.isArray(q.options)||q.options.length!==4||q.options.some(o=>!String(o?.text??o?.value??o??'').trim())||new Set((q.options||[]).map((o,i)=>String(o?.id||o?.option||['A','B','C','D'][i]||i+1).toUpperCase())).size!==4);
    const invalidKeys=qs.filter(q=>{const k=q.correct_option||q.correctOption;return !k||!Array.isArray(q.options)||!q.options.some((o,i)=>String(o?.id||o?.option||['A','B','C','D'][i]||i+1).toUpperCase()===String(k).toUpperCase());});
    const noSolutions=qs.filter(q=>!String(q.explanation||q.solution||'').trim());
    const duplicateIds=new Set(qs.map(q=>String(q.id||''))).size!==qs.length;
    if(broken.length)return {ok:false,reason:`${broken.length} question(s) are missing text or options.`};
    if(invalidKeys.length)return {ok:false,reason:`${invalidKeys.length} question(s) have a missing or invalid correct option.`};
    if(noSolutions.length)return {ok:false,reason:`${noSolutions.length} question(s) have no explanation.`};
    if(duplicateIds)return {ok:false,reason:'Duplicate question IDs were found in this selection.'};
    if(full&&(qs.length!==80||!base.complete))return {ok:false,reason:`Full-paper mode requires exactly 80 questions numbered 1–80, each with text, four options, a valid answer key and an explanation. This selection has ${qs.length} questions; verify IDs and numbering before retrying.`};
    return {ok:true};
  }
  function startTest({year,mode,title,questions,durationMinutes,full=false,untimed=false}){
    paletteFilter='all';
    const valid=canStartQuestions(questions,full);
    if(!valid.ok){notify(valid.reason,'error');return false;}
    try{
      const scheme={...CSATScoring.DEFAULT_SCHEME};if(untimed)durationMinutes=0;
      CSATExamEngine.start({year,mode,title,questions,durationMinutes,scheme,fullPaper:full});
      currentResultId=null;setPage('exam');
      if(durationMinutes>0&&settings().timerEnabled)CSATExamEngine.startClock(updateTimer,timeUp);
      return true;
    }catch(e){notify(e.message||'Unable to start this test.','error');return false;}
  }
  function updateTimer(test){const node=$('#exam-timer');if(!node)return;node.textContent=CSATScoring.fmtTime(test.remainingSeconds);node.classList.toggle('warning',test.remainingSeconds<=600&&test.remainingSeconds>300);node.classList.toggle('danger',test.remainingSeconds<=300);if(test.remainingSeconds===300&&settings().timerWarnings)notify('Five minutes remaining.','info');if(test.remainingSeconds===60&&settings().timerWarnings)notify('One minute remaining.','error');}
  function timeUp(){const test=CSATExamEngine.active();if(!test)return;if(settings().autoSubmit){notify('Time is up. Your test is being submitted.','error');submitActive(true);}else{notify('Time is up. Auto-submit is disabled; submit manually to record your result.','error');}}
  function compactResult(r){return {...r,details:r.details.map(d=>({questionId:String(d.question.id),answer:d.answer,key:d.key,result:d.result,time:d.time,topic:d.question.topic||d.question.subtopic||'Unclassified',section:d.question.section||'Unclassified',question_number:d.question.question_number}))};}
  function submitActive(auto=false){
    const test=CSATExamEngine.active();if(!test)return;
    const completed=CSATExamEngine.submit(),map=qMap(),questions=completed.questionIds.map(id=>map.get(String(id))).filter(Boolean);
    const r=CSATScoring.scoreAttempt(completed,questions);const compact=compactResult(r);
    const record={id:completed.id,status:'completed',year:completed.year,title:completed.title,mode:completed.mode,startedAt:completed.startedAt,finishedAt:completed.finishedAt,questionIds:completed.questionIds,answers:completed.answers,reviewIds:completed.reviewIds,questionTimes:completed.questionTimes,result:compact};
    const attempts=userAttempts();attempts.unshift(record);CSATStorage.save(CSATStorage.KEYS.attempts,attempts.slice(0,300));
    const mistakes=savedMistakes();r.details.forEach(d=>{if(d.result==='incorrect'){const id=String(d.question.id),old=mistakes[id]||{questionId:id,count:0};mistakes[id]={...old,questionId:id,year:d.question.year,count:Number(old.count||0)+1,lastAnswer:d.answer,correctOption:d.key,lastAttempted:completed.finishedAt};}});CSATStorage.save(CSATStorage.KEYS.mistakes,mistakes);
    currentResultId=record.id;setPage('results');notify(auto?'Test auto-submitted. Results are ready.':'Test submitted. Results are ready.','success');
  }
  function openResult(id){currentResultId=id;reviewFilter='all';setPage('results');}
  function addBookmark(id,category='Important'){
    const qs=savedBookmarks(),found=qs.findIndex(b=>String(b.questionId)===String(id));
    if(found>=0){qs.splice(found,1);CSATStorage.save(CSATStorage.KEYS.bookmarks,qs);notify('Bookmark removed.');}
    else{const q=questionById(id);qs.unshift({questionId:String(id),year:q?.year,question_number:q?.question_number,category,addedAt:new Date().toISOString()});CSATStorage.save(CSATStorage.KEYS.bookmarks,qs);notify('Question bookmarked.','success');}
    applySettings();if(page==='bookmarks'||page==='exam'||page==='review')render();
  }
  function saveNote(id,text){const notes=savedNotes();if(!String(text||'').trim())delete notes[String(id)];else notes[String(id)]={text:String(text).trim(),updatedAt:new Date().toISOString()};CSATStorage.save(CSATStorage.KEYS.notes,notes);notify('Personal note saved.','success');if(page==='notes'||page==='review')render();}
  function retryOne(id){const q=questionById(id);if(!q){notify('Question not found in the currently loaded bank.','error');return;}startTest({year:q.year,mode:'practice',title:`Retry · CSAT ${q.year} Q${q.question_number}`,questions:[q],durationMinutes:0,full:false,untimed:true});}
  function retryQuestions(qs,title){if(!qs.length){notify('No matching questions are available.','error');return;}const valid=qs.filter(q=>q.correct_option||q.correctOption);if(!valid.length){notify('No answer-keyed questions available for this retry set.','error');return;}startTest({year:'Custom',mode:'practice',title,questions:valid,durationMinutes:0,untimed:true});}
  function importBank(){importMode='bank';$('#import-file').value='';$('#import-file').click();}
  function importBackup(){importMode='backup';$('#import-file').value='';$('#import-file').click();}
  function downloadJSON(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
  function confirmAction(title,message){
    const dialog=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;
    return new Promise(resolve=>{const handler=()=>{dialog.removeEventListener('close',handler);resolve(dialog.returnValue==='confirm');};dialog.addEventListener('close',handler);if(typeof dialog.showModal==='function')dialog.showModal();else resolve(window.confirm(message));});
  }
  async function handleAction(action,target){
    const id=target?.dataset.id,year=Number(target?.dataset.year),index=Number(target?.dataset.index);
    if(action.startsWith('go-')){const lookup={'go-library':'library','go-practice':'practice','go-custom':'custom','go-analysis':'analysis','go-analytics':'analytics','go-bookmarks':'bookmarks','go-mistakes':'mistakes','go-notes':'notes','go-settings':'settings','go-import':'settings','go-results-history':'analytics'};setPage(lookup[action]||'dashboard');if(action==='go-import')setTimeout(()=>$('#data-import')?.scrollIntoView({behavior:'smooth',block:'start'}),80);return;}
    switch(action){
      case 'start-year':{const qs=CSATStorage.getQuestions(year);startTest({year,mode:'exam',title:`CSAT ${year} · Full Paper`,questions:qs,durationMinutes:120,full:true});break;}
      case 'resume-test':{const t=CSATExamEngine.resume(settings().timerEnabled?updateTimer:null,settings().timerEnabled?timeUp:null);if(t){setPage('exam');if(!settings().timerEnabled)CSATExamEngine.stopClock();}break;}
      case 'discard-test':if(await confirmAction('Discard unfinished test?','This removes the saved active test. Completed attempt history will not be changed.')){CSATExamEngine.discard();notify('Unfinished test discarded.');render();}break;
      case 'prev-question':{const t=CSATExamEngine.active();if(t){CSATExamEngine.moveTo(t.currentIndex-1);render();}break;}
      case 'next-question':{const t=CSATExamEngine.active();if(t){CSATExamEngine.moveTo(t.currentIndex+1);render();}break;}
      case 'jump-question':CSATExamEngine.moveTo(index);render();$('#question-palette')?.classList.remove('open');break;
      case 'mark-review':CSATExamEngine.toggleReview();render();break;
      case 'clear-answer':CSATExamEngine.clearAnswer();render();break;
      case 'reveal-answer':if(CSATExamEngine.active()?.mode==='practice'){CSATExamEngine.revealCurrent();render();}break;
      case 'toggle-palette':$('#question-palette')?.classList.toggle('open');break;
      case 'submit-test':{const t=CSATExamEngine.active();if(!t)break;const c=CSATExamEngine.counts(t);const ok=!settings().confirmSubmit||await confirmAction('Submit this test?',`You have answered ${c.answered} of ${c.total} questions; ${c.remaining} are unanswered and ${c.review} are marked for review. Submit now?`);if(ok)submitActive(false);break;}
      case 'toggle-bookmark':addBookmark(id);break;
      case 'remove-bookmark':addBookmark(id);break;
      case 'retry-question':retryOne(id);break;
      case 'view-question':window.reviewQuestionId=id;window.reviewAttemptId=null;setPage('review');break;
      case 'review-question':window.reviewQuestionId=id;window.reviewAttemptId=target.dataset.attempt;setPage('review');break;
      case 'back-results':setPage('results');break;
      case 'open-result':openResult(id);break;
      case 'save-note':saveNote(id,$('#review-note')?.value||'');break;
      case 'edit-note':window.reviewQuestionId=id;window.reviewAttemptId=null;setPage('review');break;
      case 'delete-note':if(await confirmAction('Delete note?','This removes the personal note for this question.')){const n=savedNotes();delete n[id];CSATStorage.save(CSATStorage.KEYS.notes,n);notify('Note deleted.');render();}break;
      case 'remove-mistake':{const m=savedMistakes();delete m[id];CSATStorage.save(CSATStorage.KEYS.mistakes,m);render();notify('Question removed from mistake book.');break;}
      case 'clear-mistakes':if(await confirmAction('Clear the mistake book?','All mistake tracking records will be removed. Original attempt history will remain.')){CSATStorage.save(CSATStorage.KEYS.mistakes,{});render();}break;
      case 'retry-mistakes':{const m=Object.values(savedMistakes());retryQuestions(m.map(x=>questionById(x.questionId)).filter(Boolean),'Retry · Mistake Book');break;}
      case 'retry-bookmarks':{const b=savedBookmarks();retryQuestions(b.map(x=>questionById(x.questionId)).filter(Boolean),'Retry · Bookmarks');break;}
      case 'export-backup':downloadJSON(`csat-command-centre-backup-${new Date().toISOString().slice(0,10)}.json`,CSATStorage.exportAll());notify('Backup export started.','success');break;
      case 'import-bank':importBank();break;
      case 'import-backup':importBackup();break;
      case 'reset-progress':if(await confirmAction('Reset all progress?','This deletes test history, bookmarks, notes, mistakes, unfinished tests and mock preferences. Imported question data and settings remain.')){CSATStorage.resetProgress();render();notify('Progress reset.');}break;
      case 'reset-settings':if(await confirmAction('Reset settings?','All appearance, exam and accessibility preferences will return to defaults. Progress and question data are preserved.')){CSATStorage.resetSettings();applySettings();render();notify('Settings restored to defaults.');}break;
      case 'clear-search':searchTerm='';setPage('search');break;
      default:break;
    }
  }
  function bindDynamic(){
    $$('[data-action]',main).forEach(el=>{if(el.dataset.bound)return;el.dataset.bound='1';el.addEventListener('click',e=>{const action=el.dataset.action;if(el.tagName==='BUTTON'&&el.type==='submit'&&el.closest('form'))return;e.preventDefault();handleAction(action,el);});});
    $$('[data-setting]',main).forEach(el=>{if(el.dataset.bound)return;el.dataset.bound='1';el.addEventListener('change',()=>{const key=el.dataset.setting,value=el.type==='checkbox'?el.checked:el.value;CSATStorage.setSetting(key,value);applySettings();if(key==='timerEnabled'&&page==='exam'){if(value){const t=CSATExamEngine.active();if(t&&t.status==='active')CSATExamEngine.startClock(updateTimer,timeUp);}else CSATExamEngine.stopClock();}if(['theme','fontSize','spacing','highContrast','reducedMotion'].includes(key))render();});});
    $$('input[name="exam-answer"]',main).forEach(el=>el.addEventListener('change',()=>{CSATExamEngine.answer(el.value);render();}));
    $('#practice-form')?.addEventListener('submit',e=>{e.preventDefault();const year=$('#practice-year').value,section=$('#practice-section').value,topic=$('#practice-topic').value,count=$('#practice-count').value,mode=$('#practice-mode').value,timing=$('#practice-timing').value,dur=Number($('#practice-minutes').value||30),order=$('#practice-order').value;
      let qs=getQuestions().filter(q=>(year==='all'||String(q.year)===year)&&matchesSection(q,section)&&(topic==='all'||q.topic===topic||q.subtopic===topic));if(order==='random')qs=qs.sort(()=>Math.random()-.5);const n=count==='all'?qs.length:Number(count);qs=qs.slice(0,n);startTest({year:year==='all'?'Custom':Number(year),mode,title:`${section} Practice · ${year==='all'?'2021–2026':year}`,questions:qs,durationMinutes:timing==='timed'?dur:0,untimed:timing==='untimed'});});
    $$('input[name="custom-year"]').forEach(el=>el.addEventListener('change',()=>{if(el.checked)$('#custom-all-years').checked=false;}));
    $('#custom-form')?.addEventListener('submit',e=>{e.preventDefault();const allYears=$('#custom-all-years').checked;const selectedYears=$$('input[name="custom-year"]:checked').map(i=>Number(i.value));const years=allYears?YEARS:(selectedYears.length?selectedYears:[]);const selectedSections=$$('input[name="custom-section"]:checked').map(i=>i.value);const mixed=$('#custom-mixed').checked;const topic=$('#custom-topic').value.trim().toLowerCase();const diff=$('#custom-difficulty').value;const count=$('#custom-count').value;const mode=$('#custom-mode').value;const duration=Number($('#custom-duration').value||120);const order=$('#custom-order').value;
      let qs=getQuestions().filter(q=>years.includes(Number(q.year))&&(mixed||selectedSections.length===0||selectedSections.some(s=>matchesSection(q,s)))&&(!topic||[q.topic,q.subtopic,q.question_text,(q.tags||[]).join(' ')].join(' ').toLowerCase().includes(topic))&&(diff==='all'||String(q.difficulty||'').toLowerCase()===diff.toLowerCase()));if(order==='random')qs=qs.sort(()=>Math.random()-.5);if(count!=='all')qs=qs.slice(0,Number(count));const yearsInSet=new Set(qs.map(q=>Number(q.year)));const numbers=[...qs].map(q=>Number(q.question_number)).sort((a,b)=>a-b);const isFull=count==='80'&&qs.length===80&&yearsInSet.size===1&&numbers.every((n,i)=>n===i+1);startTest({year:years.length===1?years[0]:'Custom',mode,title:`Custom CSAT Mock · ${qs.length} questions`,questions:qs,durationMinutes:duration,full:isFull});});
    $('#result-filter')?.addEventListener('change',e=>{reviewFilter=e.target.value;render();});
    $('#palette-section-filter')?.addEventListener('change',e=>{paletteFilter=e.target.value;render();});
    $('#notes-search')?.addEventListener('input',e=>{const term=e.target.value.toLowerCase();$$('.note-item',main).forEach(n=>n.classList.toggle('hide',!n.dataset.search.includes(term)));});
    $('#search-page-input')?.addEventListener('keydown',e=>{if(e.key==='Enter'){searchTerm=e.target.value;render();}});
  }
  $('#sidebar').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)setPage(b.dataset.page);});
  $('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
  $('#theme-toggle').addEventListener('click',()=>{const s=settings(),next=document.documentElement.dataset.theme==='dark'?'light':'dark';CSATStorage.setSetting('theme',next);applySettings();if(page==='settings')render();});
  $('#settings-shortcut').addEventListener('click',()=>setPage('settings'));
  $('#global-search').addEventListener('input',e=>{searchTerm=e.target.value;});
  $('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.value.trim()){e.preventDefault();searchTerm=e.target.value.trim();setPage('search');}});
  document.addEventListener('keydown',e=>{
    if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus();return;}
    const t=CSATExamEngine.active();if(!t||t.status!=='active'||!settings().keyboardShortcuts)return;
    if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
    if(['1','2','3','4'].includes(e.key)){const q=questionById(t.questionIds[t.currentIndex]);const option=q?.options?.[Number(e.key)-1];if(option){e.preventDefault();CSATExamEngine.answer(String(option.id||option.option||['A','B','C','D'][Number(e.key)-1]));render();}}
    else if(e.key==='ArrowLeft'){e.preventDefault();CSATExamEngine.moveTo(t.currentIndex-1);render();}
    else if(e.key==='ArrowRight'){e.preventDefault();CSATExamEngine.moveTo(t.currentIndex+1);render();}
    else if(e.key.toLowerCase()==='m'){e.preventDefault();CSATExamEngine.toggleReview();render();}
    else if(e.key.toLowerCase()==='c'){e.preventDefault();CSATExamEngine.clearAnswer();render();}
    else if(e.key.toLowerCase()==='s'){e.preventDefault();const b=$('[data-action="submit-test"]',main);if(b)b.click();}
  });
  $('#import-file').addEventListener('change',async e=>{
    const file=e.target.files?.[0];if(!file)return;
    try{
      const data=JSON.parse(await file.text());
      if(importMode==='bank'){
        const result=CSATStorage.storeQuestionBank(data);notify(`Imported ${result.years.map(y=>`${y}: ${result.counts[y]}`).join(', ')} questions.`, 'success');
      }else{CSATStorage.importBackup(data);notify('Backup restored.','success');}
      applySettings();setPage('dashboard');
    }catch(err){notify(err.message||'Import failed. Check the JSON structure and retry.','error');}
    e.target.value='';
  });
  function boot(){applySettings();
    const s=settings();if(window.matchMedia){window.matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(settings().theme==='system')applySettings();});}
    const active=CSATExamEngine.active();if(active&&active.status==='active'){// Preserve the test state; the dashboard offers an explicit Resume action.
      notify('An unfinished test was recovered. Resume it from the dashboard when ready.','info');
    }
    render();
  }
  boot();
})();
